using System.Collections.Generic;
using UnityEngine;
namespace Sagara.Dermaga.Fishing {
public sealed class FishingPresentation : MonoBehaviour {
 public Transform hand;
 public GameObject rodPrefab;
 GameObject rodModel;
 bool pulling; Vector3 caughtFish;
 Transform rodTip;
 public Material rodMaterial,lineMaterial,waterMaterial,bobberMaterial,auraTemplate;
 public AudioSource audioSource;
 GameObject root,bobber,softAura; Material softAuraMaterial;float nextGlitter;LineRenderer rod,line;
 readonly List<LineRenderer> rings=new List<LineRenderer>();
 readonly List<AudioClip> tones=new List<AudioClip>();
 Material auraMaterial; Vector3 destination,start;
 Color aura=Color.white;float intensity=1;
 void Awake(){if(audioSource==null){audioSource=gameObject.AddComponent<AudioSource>();audioSource.playOnAwake=false;audioSource.spatialBlend=0;audioSource.volume=.15f;}foreach(float hz in new[]{350f,850f,600f,180f,1100f,250f}){var clip=AudioClip.Create("FishingPrototypeTone",6615,1,44100,false);var samples=new float[6615];for(int i=0;i<samples.Length;i++)samples[i]=Mathf.Sin(i*hz*2*Mathf.PI/44100)*.2f*(1-i/(float)samples.Length);clip.SetData(samples,0);tones.Add(clip);}}
 LineRenderer MakeLine(string name,Transform parent,Material material,float width){var g=new GameObject(name);g.transform.SetParent(parent,false);var r=g.AddComponent<LineRenderer>();r.sharedMaterial=material;r.useWorldSpace=true;r.startWidth=r.endWidth=width;r.numCapVertices=4;return r;}
 public void Begin(FishingSession session){Clear();pulling=false;root=new GameObject("FishingSessionVisuals");root.transform.SetParent(transform,false);destination=session.ActiveSpot.CastPosition;start=hand!=null?hand.position:session.player.transform.position+Vector3.up;rod=MakeLine("PrototypeRod_HandFollow",root.transform,rodMaterial,.035f);rod.positionCount=2;if(rodPrefab!=null){rodModel=Instantiate(rodPrefab,root.transform);rodTip=rodModel.transform.Find("LineTip");rod.enabled=false;}line=MakeLine("FishingLine",root.transform,lineMaterial,.012f);line.positionCount=16;bobber=GameObject.CreatePrimitive(PrimitiveType.Sphere);bobber.name="PrototypeBobber";bobber.transform.SetParent(root.transform,false);bobber.transform.localScale=new Vector3(.16f,.22f,.16f);Destroy(bobber.GetComponent<Collider>());bobber.GetComponent<Renderer>().sharedMaterial=bobberMaterial;
 auraMaterial=new Material(waterMaterial);auraMaterial.color=Color.white;for(int i=0;i<3;i++){var ring=MakeLine("AnimatedWaterRipple_"+i,root.transform,auraMaterial,.025f);ring.positionCount=49;ring.loop=true;rings.Add(ring);}if(auraTemplate!=null){softAura=GameObject.CreatePrimitive(PrimitiveType.Quad);softAura.name="SoftRarityAura";softAura.transform.SetParent(root.transform,false);softAura.transform.position=destination+Vector3.up*.012f;softAura.transform.rotation=Quaternion.Euler(90,0,0);softAuraMaterial=new Material(auraTemplate);softAura.GetComponent<Renderer>().sharedMaterial=softAuraMaterial;Destroy(softAura.GetComponent<Collider>());softAura.SetActive(false);}aura=Color.white;intensity=1;nextGlitter=0;Tone(0);}
 public void Animate(FishingSession session){if(root==null||bobber==null)return;var grip=hand!=null?hand.position:session.player.transform.position+Vector3.up;var toward=(destination-grip).normalized;var tip=grip+Vector3.up*.6f+toward*1.5f;if(session.State==FishingState.Casting){float p=session.PhaseProgress;tip=grip+Vector3.Lerp(Vector3.up*1.8f,toward*1.5f+Vector3.up*.6f,p);bobber.transform.position=Vector3.Lerp(start,destination,p)+Vector3.up*Mathf.Sin(p*Mathf.PI)*2.4f;}else bobber.transform.position=destination+Vector3.up*Mathf.Sin(Time.time*3)*.035f;
 if(pulling)bobber.transform.position=caughtFish;float resultFade=session.State==FishingState.CatchFail?1-session.PhaseProgress:session.State==FishingState.CatchSuccess?1-session.PhaseProgress:1;if(softAuraMaterial!=null){var faded=softAuraMaterial.color;faded.a=.22f*resultFade;softAuraMaterial.color=faded;}if(softAura!=null&&softAura.activeSelf){softAura.transform.localScale=Vector3.one*(2.1f*intensity+Mathf.Sin(Time.time*2)*.15f);if(session.Selected!=null&&session.Selected.rarity==FishRarity.Legendary&&Time.time>nextGlitter){nextGlitter=Time.time+1.2f;Splash(destination,aura,6);}}rod.SetPosition(0,grip);rod.SetPosition(1,tip);if(rodModel!=null){rodModel.transform.position=grip;rodModel.transform.rotation=Quaternion.FromToRotation(Vector3.up,(tip-grip).normalized);if(rodTip!=null)tip=rodTip.position;}for(int i=0;i<16;i++){float p=i/15f;line.SetPosition(i,Vector3.Lerp(tip,bobber.transform.position,p)-Vector3.up*Mathf.Sin(p*Mathf.PI)*.1f);}for(int i=0;i<rings.Count;i++){float phase=Mathf.Repeat(Time.time*.45f+i/3f,1);float radius=.15f+phase*(session.State==FishingState.Minigame||session.State==FishingState.BiteDetected ? .65f*intensity:.4f);var ring=rings[i];ring.startWidth=ring.endWidth=.018f+intensity*.008f;var col=Color.Lerp(new Color(.3f,.8f,.85f),aura,.8f)*(1-phase*.45f);col.a=resultFade;ring.startColor=ring.endColor=col;for(int j=0;j<49;j++){float angle=j/48f*Mathf.PI*2;ring.SetPosition(j,destination+new Vector3(Mathf.Cos(angle)*radius,.015f+i*.003f,Mathf.Sin(angle)*radius));}}}
 public void Bite(RaritySettings settings){aura=settings.aura;if(softAura!=null){softAura.SetActive(true);softAuraMaterial.color=new Color(aura.r,aura.g,aura.b,.22f);}if(auraMaterial!=null)auraMaterial.color=aura;intensity=settings.intensity;Tone(1);Splash(destination,aura,settings.rarity==FishRarity.Legendary?24:10);}
 public void InputFeedback(bool correct){Tone(correct?2:3);}
 public void Result(bool success,RaritySettings rarity){Tone(success?4:5);Splash(destination,success?rarity.aura:new Color(.4f,.65f,.8f),success?18:5);pulling=success;caughtFish=destination;if(!success)FinishPull();if(bobber!=null)bobber.SetActive(false);}
 public void Splash(Vector3 position,Color color,int count){if(root==null)return;var g=new GameObject("PrototypeSplash");g.transform.SetParent(root.transform,false);g.transform.position=position;var ps=g.AddComponent<ParticleSystem>();ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=ps.main;main.loop=false;main.duration=.6f;main.startLifetime=.65f;main.startSpeed=1.2f;main.startSize=.06f;main.startColor=color;main.gravityModifier=.4f;var em=ps.emission;em.rateOverTime=0;em.SetBursts(new[]{new ParticleSystem.Burst(0,(short)count)});ps.GetComponent<ParticleSystemRenderer>().sharedMaterial=waterMaterial;ps.Play();Destroy(g,1.5f);}
 public void FollowCaughtFish(Vector3 position){caughtFish=position;if(line!=null&&line.positionCount>0)line.SetPosition(line.positionCount-1,position);}
 public void FinishPull(bool hideWaterFeedback=false){if(hideWaterFeedback){foreach(var ring in rings)ring.gameObject.SetActive(false);if(softAura!=null)softAura.SetActive(false);}pulling=false;if(rodModel!=null)rodModel.SetActive(false);if(rod!=null)rod.gameObject.SetActive(false);if(line!=null)line.gameObject.SetActive(false);}
 void Tone(int index){if(audioSource!=null&&tones.Count>index)audioSource.PlayOneShot(tones[index]);}
 public void Clear(){rings.Clear();if(root!=null)Destroy(root);root=null;bobber=null;softAura=null;rodModel=null;rodTip=null;if(softAuraMaterial!=null)Destroy(softAuraMaterial);softAuraMaterial=null;if(auraMaterial!=null)Destroy(auraMaterial);auraMaterial=null;}
 void OnDestroy(){Clear();foreach(var clip in tones)if(clip!=null)Destroy(clip);}
}
}